require_once __DIR__.'/receipt-files.php';require_once __DIR__.'/board-report.php';
function mkt_schema(PDO $db): void {$db->exec("CREATE TABLE IF NOT EXISTS marketing_imports(id INTEGER PRIMARY KEY AUTOINCREMENT,token TEXT UNIQUE NOT NULL,name TEXT NOT NULL,path TEXT NOT NULL,extension TEXT NOT NULL,data_date TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',config TEXT NOT NULL DEFAULT '{}',summary TEXT NOT NULL DEFAULT '{}');CREATE TABLE IF NOT EXISTS marketing_rows(id INTEGER PRIMARY KEY AUTOINCREMENT,row_key TEXT UNIQUE NOT NULL,scope_key TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,import_id INTEGER NOT NULL,day TEXT NOT NULL,account TEXT NOT NULL,campaign TEXT NOT NULL,campaign_id TEXT NOT NULL,ad TEXT NOT NULL,ad_id TEXT NOT NULL,sku TEXT NOT NULL,gender TEXT NOT NULL,spend REAL NOT NULL,fee REAL,orders REAL,source_row INTEGER NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS marketing_rows_date ON marketing_rows(day,sku,gender);CREATE TABLE IF NOT EXISTS marketing_policy(id INTEGER PRIMARY KEY CHECK(id=1),cost_mode TEXT NOT NULL,fee_percent REAL NOT NULL,order_source TEXT NOT NULL)");$cols=array_column($db->query("PRAGMA table_info(marketing_rows)")->fetchAll(),"name");if(!in_array("scan_value",$cols,true))$db->exec("ALTER TABLE marketing_rows ADD COLUMN scan_value REAL");if(!in_array("account_name",$cols,true))$db->exec("ALTER TABLE marketing_rows ADD COLUMN account_name TEXT NOT NULL DEFAULT ''");}
function mkt_campaign_name(string $name):string {$name=preg_replace('/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2060}\x{FEFF}]/u','',$name);return trim(preg_replace('/\s*(?:Biểu đồ|Chỉnh sửa|Nhân bản|Mở menu thả xuống|Edit|Duplicate|Open dropdown menu).*$/iu','',$name));}
function mkt_effective_rows(PDO $db,array $range,string $sku='',string $kind='all'):array {
 $q=$db->prepare('SELECT * FROM marketing_rows WHERE active=1 AND day>=? AND day<=? ORDER BY import_id,id');$q->execute([$range['from'],$range['to']]);$unique=[];$latest=[];$catalog=board_catalog($db);
 foreach($q as $r){$r['campaign']=mkt_campaign_name($r['campaign']);$stored=trim($r['sku']);if($stored===''||mkt_campaign_name($stored)===$r['campaign']||$stored===trim($r['ad']))$r['sku']=mkt_screen_sku($r['campaign'],$r['ad']);$r['gender']=mkt_gender($r['sku'],$catalog,$r['gender']);$key=json_encode([$r['day'],report_fold($r['account']),$r['campaign_id']?:report_fold($r['campaign']),$r['ad_id']?:report_fold($r['ad'])]);$unique[$key]=$r;$group=$r['day'].'|'.report_fold($r['account']);$latest[$group]=max($latest[$group]??0,(int)$r['import_id']);}
 return array_values(array_filter($unique,static fn($r)=>(int)$r['import_id']===$latest[$r['day'].'|'.report_fold($r['account'])]&&($sku===''||$r['sku']===$sku)&&($kind==='all'||product_sku_kind($catalog,$r['sku'],$r['day'])===$kind)));
}
function mkt_screen_sku(string $campaign,string $ad=''):string {
 foreach([$campaign,$ad] as $text){$text=preg_replace('/^\s*(?:(?:Set|TEST|mới|mồi)\s+)+/iu','',$text);if(preg_match('/^\s*([A-Z][A-Z0-9_-]*[0-9][A-Z0-9_-]*)(?=\s|$)/iu',$text,$m))return mb_strtoupper($m[1],'UTF-8');}
 return trim($campaign?:$ad);
}
function mkt_gender(string $sku,array $catalog,string $fallback=''):string {return $sku==='E1234'?'Nam':($catalog[$sku]['gender']??$fallback);}
function mkt_reclassify(PDO $db):int {
 $catalog=board_catalog($db);$rows=$db->query("SELECT id,campaign,ad FROM marketing_rows WHERE sku='' AND active=1")->fetchAll();$save=$db->prepare("UPDATE marketing_rows SET sku=?,gender=? WHERE id=? AND sku=''");$count=0;
 foreach($rows as $r){$sku=mkt_screen_sku($r['campaign'],$r['ad']);if($sku==='')continue;$save->execute([$sku,$catalog[$sku]['gender']??'',$r['id']]);$count+=$save->rowCount();}return $count;
}
function mkt_number($value): ?float {
 $text=trim((string)$value);if($text===''||in_array($text,['—','–','-'],true))return null;$text=preg_replace('/(?:VND|VNĐ|USD|₫|đ|\$|\s|\x{00a0})/iu','',$text);if(preg_match('/^\((.*)\)$/D',$text,$m))$text='-'.$m[1];
 if(str_contains($text,',')&&str_contains($text,'.')){$decimal=strrpos($text,',')>strrpos($text,'.')?',':'.';$text=str_replace($decimal===','?'.':',','',$text);if($decimal===',')$text=str_replace(',','.',$text);}elseif(preg_match('/^-?\d{1,3}(?:[.,]\d{3})+$/D',$text))$text=str_replace([',','.'],'',$text);else $text=str_replace(',','.',$text);
 if(!is_numeric($text))return null;$number=(float)$text;return is_finite($number)&&abs($number)<=1000000000000?$number:null;
}
function mkt_day($value,string $fallback): ?string {
 $value=trim((string)$value);if($value==='')return $fallback;
 if(is_numeric($value)&&(float)$value>=20000&&(float)$value<=100000)return (new DateTimeImmutable('1899-12-30'))->modify('+'.(int)(float)$value.' days')->format('Y-m-d');
 foreach(['!Y-m-d','!d/m/Y','!d-m-Y','!d.m.Y','!Y-m-d H:i:s','!d/m/Y H:i:s'] as $format){$day=DateTimeImmutable::createFromFormat($format,$value);$errors=DateTimeImmutable::getLastErrors();if($day&&(!$errors||(!$errors['warning_count']&&!$errors['error_count'])))return $day->format('Y-m-d');}return null;
}
function mkt_text_table(string $text): array {$lines=preg_split('/\r\n|\n|\r/',$text);$probe=implode("\n",array_slice($lines,0,20));$separator=str_contains($probe,"\t")?"\t":(substr_count($probe,';')>substr_count($probe,',')?';':',');$rows=[];foreach($lines as $line)if(trim($line)!==''){$cells=str_getcsv($line,$separator);if(count($cells)>512||count($rows)>=50000)throw new RuntimeException('Bảng quá lớn.',413);$rows[]=$cells;}if(array_sum(array_map('count',$rows))>500000)throw new RuntimeException('Bảng quá lớn.',413);return ['Dữ liệu dán'=>$rows];}
function mkt_tables(array $upload): array {return $upload['extension']==='tsv'?mkt_text_table(file_get_contents($upload['path'])):receipt_file_tables($upload['path'],$upload['extension']);}
function mkt_columns(array $headers): array {
 $map=[];$aliases=['end_day'=>['KET THUC BAO CAO','REPORTING ENDS'],'day'=>['NGAY','DATE','DAY','NGAY BAO CAO','REPORTING STARTS','BAT DAU BAO CAO'],'spend'=>['CHI TIEU','SO TIEN DA CHI TIEU','AMOUNT SPENT','SPEND','CHI PHI QUANG CAO'],'fee'=>['PHI KHAC','PHU PHI','EXTRA FEE'],'orders'=>['SO DON','DON HANG','LUOT MUA','PURCHASES','WEBSITE PURCHASES','LUOT MUA HANG TREN TRANG WEB'],'campaign'=>['TEN CHIEN DICH','CHIEN DICH','CAMPAIGN NAME','CAMPAIGN'],'campaign_id'=>['ID CHIEN DICH','CAMPAIGN ID'],'ad'=>['TEN QUANG CAO','AD NAME'],'ad_id'=>['ID QUANG CAO','AD ID'],'sku'=>['MA SAN PHAM','MA SP','SKU','SAN PHAM'],'gender'=>['GIOI TINH','NHOM','NAM/NU'],'account'=>['TAI KHOAN','TEN TAI KHOAN','ACCOUNT NAME','ACCOUNT']];
 foreach($headers as $c=>$h){$h=report_fold((string)$h);foreach($aliases as $key=>$names)foreach($names as $name)if(($h===$name||preg_match('/^'.preg_quote($name,'/').'\s*\((?:VND|VNĐ|USD|Đ)\)$/u',$h))&&!isset($map[$key])){$map[$key]=(int)$c;break;}}return $map;
}
function mkt_preview(array $upload): array {$tables=mkt_tables($upload);$result=[];foreach($tables as $name=>$rows){$best=null;foreach($rows as $r=>$cells){if((int)$r>30)break;$map=mkt_columns($cells);if(isset($map['spend'])&&(isset($map['campaign'])||isset($map['campaign_id']))){$best=['headerRow'=>(int)$r,'headers'=>$cells,'map'=>$map];break;}}if(!$best){$r=array_key_first($rows);$best=['headerRow'=>(int)($r??0),'headers'=>$rows[$r]??[],'map'=>mkt_columns($rows[$r]??[])];}$best['sheet']=$name;$best['rowCount']=count($rows);$best['sample']=array_slice(array_values(array_filter($rows,static fn($r)=>$r>$best['headerRow'],ARRAY_FILTER_USE_KEY)),0,5);$width=0;foreach($best['sample'] as $sample)$width=max($width,count($sample));for($c=0;$c<$width;$c++)$best['headers'][$c]??='Cột '.($c+1);$result[]=$best;}return $result;}
function mkt_parse(array $tables,array $config,array $catalog): array {
 $rows=$tables[$config['sheet']??'']??null;if(!$rows)throw new RuntimeException('Chọn sheet dữ liệu.',400);$map=$config['map']??[];if(!isset($map['spend'])||(!isset($map['campaign'])&&!isset($map['campaign_id'])))throw new RuntimeException('Cần chọn cột chi tiêu và chiến dịch.',400);$fallback=(string)($config['date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$fallback)||mkt_day($fallback,'')!==$fallback)throw new RuntimeException('Chọn ngày dữ liệu.',400);$exchange=(float)($config['exchange']??1);if(!is_finite($exchange)||$exchange<=0||$exchange>1000000000)throw new RuntimeException('Tỷ giá quy đổi không hợp lệ.',400);
 $parsed=[];$issues=[];$errors=[];$moneyHeader=(string)($rows[(int)($config['headerRow']??0)][(int)$map['spend']]??'');if(($config['currency']??'VND')==='VND'&&(preg_match('/USD|\$/i',$moneyHeader)||$exchange!==1.0))throw new RuntimeException('Chọn đơn vị ngoại tệ và tỷ giá phù hợp.',400);$skus=array_keys($catalog);usort($skus,static fn($a,$b)=>strlen($b)<=>strlen($a));$pattern=$skus?'/(?<![A-Z0-9])('.implode('|',array_map(static fn($s)=>preg_quote($s,'/'),$skus)).')(?![A-Z0-9])/i':'/(?!) /';
 foreach($rows as $r=>$cells){if((int)$r<=(int)($config['headerRow']??0))continue;if(!array_filter($cells,static fn($v)=>trim((string)$v)!==''))continue;$get=static fn($key)=>isset($map[$key])?trim((string)($cells[(int)$map[$key]]??'')):'';$campaign=mkt_campaign_name($get('campaign'));$campaignId=$get('campaign_id');if($campaign===''&&$campaignId==='')continue;if(preg_match('/^(TỔNG(?:\s|$)|TOTAL(?:\s|$)|RESULTS FROM|KẾT QUẢ TỪ)/iu',$campaign))continue;
  if(($config['currency']??'VND')==='VND'&&preg_match('/USD|\$/i',$get('spend'))){$errors[]=['row'=>(int)$r+1,'text'=>'Chi tiêu có đơn vị ngoại tệ. Chọn tỷ giá trước khi lưu.'];continue;}$day=mkt_day($get('day'),$fallback);if($get('end_day')!==''&&mkt_day($get('end_day'),$fallback)!==$day){$errors[]=['row'=>(int)$r+1,'text'=>'Chi tiêu gộp nhiều ngày. Chọn phân tích theo từng ngày trên màn hình quảng cáo rồi chuyển lại.'];continue;}$spend=mkt_number($get('spend'));$fee=mkt_number($get('fee'));$orders=mkt_number($get('orders'));$account=$get('account')?:trim((string)($config['account']??''));if(!$day||$spend===null||$spend<0||($get('fee')!==''&&$fee===null)||$account===''){$errors[]=['row'=>(int)$r+1,'text'=>!$day?'Ngày không đọc được':($account===''?'Thiếu tài khoản / nguồn dữ liệu':'Chi tiêu hoặc phụ phí không đọc được')];continue;}if($orders!==null&&$orders<0){$errors[]=['row'=>(int)$r+1,'text'=>'Số đơn không được âm'];continue;}
  $explicit=mb_strtoupper($get('sku'),'UTF-8');$sku=$explicit;$inferred=[];if($sku===''){$sku=mkt_screen_sku($campaign,$get('ad'));if($sku==='')$sku=mb_strtoupper(trim((string)($config['default_sku']??'')),'UTF-8');}
  $gender=mkt_gender($sku,$catalog);$sourceGender=report_fold($get('gender'));if($gender==='')$gender=$sourceGender==='NAM'?'Nam':($sourceGender==='NU'?'Nữ':'');
  $ad=$get('ad');$adId=$get('ad_id');$scope=hash('sha256',json_encode([$day,report_fold($account),$campaignId?:report_fold($campaign),$adId?:report_fold($ad)],JSON_UNESCAPED_UNICODE));$rowKey=hash('sha256',$scope.'|'.$sku.'|'.$gender);$value=['row_key'=>$rowKey,'scope_key'=>$scope,'day'=>$day,'account'=>$account,'campaign'=>$campaign?:$campaignId,'campaign_id'=>$campaignId,'ad'=>$ad,'ad_id'=>$adId,'sku'=>$sku,'gender'=>$gender,'spend'=>$spend*$exchange,'fee'=>$fee===null?null:$fee*$exchange,'orders'=>$orders,'scan_value'=>isset($map['value'])?mkt_number($get('value')):null,'account_name'=>trim((string)($config['account_name']??'')),'source_row'=>(int)$r+1];
  $parsed[$rowKey]=$value;
