function mkt_import(PDO $db,int $id,array $config,array $user): array {
 $q=$db->prepare('SELECT * FROM marketing_imports WHERE id=?');$q->execute([$id]);$source=$q->fetch();if(!$source)throw new RuntimeException('Không tìm thấy nguồn dữ liệu.',404);if($source['status']==='applied')return json_decode($source['summary'],true,512,JSON_THROW_ON_ERROR);$data=mkt_parse(mkt_tables($source),$config,board_catalog($db));if($data['errors'])throw new RuntimeException('Cần sửa dòng '.$data['errors'][0]['row'].': '.$data['errors'][0]['text'],400);if(!$data['rows'])throw new RuntimeException('Chưa có dòng chiến dịch hợp lệ.',400);
 $db->exec('BEGIN IMMEDIATE');try{
  $q=$db->prepare('SELECT status,summary FROM marketing_imports WHERE id=?');$q->execute([$id]);$check=$q->fetch();if($check['status']==='applied'){$db->exec('COMMIT');return json_decode($check['summary'],true,512,JSON_THROW_ON_ERROR);}
  $now=gmdate('c');$find=$db->prepare('SELECT id FROM marketing_rows WHERE row_key=?');$retire=$db->prepare('UPDATE marketing_rows SET active=0 WHERE day=? AND account=?');$snapshots=[];
  foreach($data['rows'] as $row)$snapshots[$row['day'].'|'.report_fold($row['account'])]=[$row['day'],$row['account']];$newer=$db->prepare('SELECT MAX(import_id) FROM marketing_rows WHERE active=1 AND day=? AND account=?');foreach($snapshots as $pair){$newer->execute($pair);if((int)$newer->fetchColumn()>$id)throw new RuntimeException('Tài khoản/ngày này đã có bản quét mới hơn. Quét lại để cập nhật.',409);$retire->execute($pair);}

  $save=$db->prepare('INSERT INTO marketing_rows(row_key,scope_key,active,import_id,day,account,campaign,campaign_id,ad,ad_id,sku,gender,spend,fee,orders,source_row,updated_at,scan_value,account_name) VALUES(?,?,1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(row_key) DO UPDATE SET active=1,import_id=excluded.import_id,campaign=excluded.campaign,campaign_id=excluded.campaign_id,ad=excluded.ad,ad_id=excluded.ad_id,sku=excluded.sku,gender=excluded.gender,spend=excluded.spend,fee=excluded.fee,orders=excluded.orders,source_row=excluded.source_row,updated_at=excluded.updated_at,scan_value=excluded.scan_value,account_name=excluded.account_name');
  $added=0;$updated=0;foreach($data['rows'] as $row){$find->execute([$row['row_key']]);if($find->fetchColumn())$updated++;else $added++;$save->execute([$row['row_key'],$row['scope_key'],$id,$row['day'],$row['account'],$row['campaign'],$row['campaign_id'],$row['ad'],$row['ad_id'],$row['sku'],$row['gender'],$row['spend'],$row['fee'],$row['orders'],$row['source_row'],$now,$row['scan_value'],$row['account_name']]);}
  $summary=['added'=>$added,'updated'=>$updated,'spend'=>$data['spend'],'issues'=>$data['issues']];$db->prepare('UPDATE marketing_imports SET status=?,config=?,summary=? WHERE id=?')->execute(['applied',json_encode($config,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),json_encode($summary,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);people_audit('marketing_import',(string)$id,$summary,$db);$db->exec('COMMIT');return $summary;
 }catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}

function mkt_reconciliation(PDO $db,array $range):array {
 $groups=[];foreach(mkt_effective_rows($db,$range) as $r){$key=$r['day'].'|'.$r['account'];$groups[$key]??=['day'=>$r['day'],'accountId'=>$r['account'],'account'=>$r['account_name']?:$r['account'],'spend'=>0.0,'orders'=>0.0,'importId'=>(int)$r['import_id']];$groups[$key]['spend']+=(float)$r['spend'];$groups[$key]['orders']+=(float)($r['orders']??0);}
 $q=$db->prepare('SELECT config,created_at FROM marketing_imports WHERE id=?');foreach($groups as &$g){$q->execute([$g['importId']]);$source=$q->fetch();$config=json_decode($source['config']??'{}',true)?:[];$v=$config['verification']??null;$g['receivedAt']=$source['created_at']??null;$g['metaSpend']=is_array($v)?mkt_number($v['spend']??''):null;$g['metaOrders']=is_array($v)?mkt_number($v['orders']??''):null;$g['difference']=$g['metaSpend']===null?null:$g['spend']-$g['metaSpend'];$g['verified']=($config['scan_version']??0)===2&&$g['difference']!==null&&abs($g['difference'])<=1&&$g['orders']===$g['metaOrders'];}unset($g);return array_values($groups);
}
function mkt_policy(PDO $db): ?array {return ['cost_mode'=>'spend_only','fee_percent'=>0.0,'order_source'=>'board'];}
function mkt_order_counts(PDO $db,string $source,array $range,string $sku,?array $board=null): array {
 $result=['total'=>0,'Nam'=>0,'Nữ'=>0,'products'=>[]];$catalog=board_catalog($db);
 $add=static function(array $skus,array $genders)use(&$result,$sku){$skus=array_values(array_unique(array_filter($skus)));if($sku!==''&&!in_array($sku,$skus,true))return;$result['total']++;foreach(array_unique($genders) as $g)if(isset($result[$g]))$result[$g]++;foreach($skus as $s)$result['products'][$s]=($result['products'][$s]??0)+1;};
 if($source==='board'){foreach(($board??board_rows($db,$catalog))['rows'] as $row)if($row['date']>=$range['from']&&$row['date']<=$range['to'])$add(array_column($row['items'],'sku'),[$row['gender']]);}
 elseif($source==='web'){$zone=new DateTimeZone('Asia/Ho_Chi_Minh');$utc=new DateTimeZone('UTC');$from=(new DateTimeImmutable($range['from'],$zone))->setTimezone($utc)->format('Y-m-d\TH:i:s\Z');$to=(new DateTimeImmutable($range['to'],$zone))->modify('+1 day')->setTimezone($utc)->format('Y-m-d\TH:i:s\Z');$q=$db->prepare('SELECT * FROM orders o WHERE created_at>=? AND created_at<? AND NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code)');$q->execute([$from,$to]);foreach($q as $raw){$order=admin_order($raw);$codes=array_column($order['items'],'sku');$genders=[];foreach($codes as $code)if(isset($catalog[$code]))$genders[]=$catalog[$code]['gender'];$add($codes,$genders);}}
 return $result;
}
function mkt_report(PDO $db,array $input,?array $board=null,?array $catalog=null): array {
 $catalog??=board_catalog($db);$range=report_range($input);$sku=mb_strtoupper(trim((string)($input['sku']??'')),'UTF-8');$query=report_fold(trim((string)($input['campaign']??'')));$rows=mkt_effective_rows($db,$range,$sku,(string)($input['product_kind']??'all'));if(count($rows)>100000)throw new RuntimeException('Thu hẹp khoảng ngày để xem tối đa 100.000 dòng MKT.',413);if($query!=='')$rows=array_values(array_filter($rows,static fn($r)=>str_contains(report_fold($r['campaign'].' '.$r['account']),$query)));$policy=mkt_policy($db);
 $empty=static fn()=>['spend'=>0.0,'fees'=>0.0,'feeComplete'=>true,'adsOrders'=>0.0,'ordersComplete'=>true,'rows'=>0,'scanValue'=>0.0,'valueComplete'=>true];$groups=['total'=>$empty(),'Nam'=>$empty(),'Nữ'=>$empty(),'unclassified'=>$empty()];$products=[];$campaigns=[];$daily=[];
 $sum=static function(array &$target,array $r){$target['spend']+=(float)$r['spend'];$target['fees']+=(float)($r['fee']??0);$target['feeComplete']=$target['feeComplete']&&$r['fee']!==null;$target['adsOrders']+=(float)($r['orders']??0);$target['ordersComplete']=$target['ordersComplete']&&$r['orders']!==null;$target['rows']++;$target['scanValue']+=(float)($r['scan_value']??0);$target['valueComplete']=$target['valueComplete']&&($r['scan_value']??null)!==null;};
 foreach($rows as $r){$sum($groups['total'],$r);$sum($groups[in_array($r['gender'],['Nam','Nữ'],true)?$r['gender']:'unclassified'],$r);$key=$r['sku'];$products[$key]??=['sku'=>$key,'name'=>($catalog[$r['sku']]['name']??($r['sku']?:'Chưa xác định mã'))]+$empty();$sum($products[$key],$r);$c=$r['account'].'|'.($r['campaign_id']?:$r['campaign']);$campaigns[$c]??=['account'=>$r['account_name']?:'Chưa có tên tài khoản','accountId'=>$r['account'],'sku'=>$r['sku'],'campaign'=>$r['campaign'],'campaign_id'=>$r['campaign_id']]+$empty();$sum($campaigns[$c],$r);$daily[$r['day']]??=['day'=>$r['day']]+$empty();$sum($daily[$r['day']],$r);}
